# مولّد الجمل العامة والتسميات وسجلّ الأخطاء (المحتوى v2). يكتب content/strings/*.json وcontent/errors.json
import json, os, ast
def nodup(path):   # مفتاحٌ مكرّر في قاموس يُبطل الأول صامتاً (الدرس 139؛ بوابة S1-U4: وسم خطأ جديد باسم وسمٍ قائم محاه): يوقف التوليد
  dups = []
  for node in ast.walk(ast.parse(open(path, encoding='utf-8').read())):
    if isinstance(node, ast.Dict):
      ks = [k.value for k in node.keys if isinstance(k, ast.Constant) and isinstance(k.value, str)]
      dups += ['%s (السطر %d)' % (k, node.lineno) for k in sorted(set(ks)) if ks.count(k) > 1]
  if dups: raise SystemExit('%s: مفتاح مكرّر في قاموس: %s' % (os.path.basename(path), '، '.join(dups)))
nodup(__file__)
OUT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'content'))   # محتوى المستودع الذي فيه المولّد، لا مسار ثابت (الفحص المستقل E: نسخة الفاحص كتبت في المستودع الأصلي)
